<?php
declare(strict_types=1);
function mcSchema(PDO $db): void {$db->exec('CREATE TABLE IF NOT EXISTS managed_coupons(code TEXT PRIMARY KEY,percent INTEGER NOT NULL,minQuantity INTEGER NOT NULL,distinctGames INTEGER NOT NULL,expires INTEGER NOT NULL,useLimit INTEGER NOT NULL,state TEXT NOT NULL,created INTEGER NOT NULL)');}
function mcGet(PDO $db,string $code): ?array {mcSchema($db);$q=$db->prepare('SELECT * FROM managed_coupons WHERE code=?');$q->execute([$code]);$r=$q->fetch(PDO::FETCH_ASSOC);return $r?:null;}
function mcCounts(PDO $db,string $code): array {$q=$db->prepare('SELECT status,COUNT(*) n FROM reward_orders WHERE coupon=? AND status<>"expired" GROUP BY status');$q->execute([$code]);$used=0;$reserved=0;foreach($q as $r){if($r['status']==='payment_verified')$used+=(int)$r['n'];else $reserved+=(int)$r['n'];}return [$used,$reserved];}
function mcPublic(PDO $db,array $r): array {[$u,$p]=mcCounts($db,$r['code']);$status=$r['state'];if($status==='active')$status=$r['expires']&&time()>=(int)$r['expires']?'Expired':((int)$r['useLimit']&&$u+$p>=(int)$r['useLimit']?($p?'Reserved':'Used'):'Available');return ['code'=>$r['code'],'percent'=>(int)$r['percent'],'minQuantity'=>(int)$r['minQuantity'],'distinct'=>(bool)$r['distinctGames'],'expires'=>(int)$r['expires'],'useLimit'=>(int)$r['useLimit'],'status'=>ucfirst($status),'used'=>$u,'reserved'=>$p];}
function mcValidate(PDO $db,string $code,array $rows,array $products): array {$r=mcGet($db,$code);if(!$r||mcPublic($db,$r)['status']!=='Available')throw new InvalidArgumentException('Coupon unavailable, expired, or fully used.');$qty=0;$titles=[];$seen=[];foreach($rows as $row){$id=$row['id']??'';$n=$row['quantity']??0;if(!is_string($id)||isset($seen[$id])||!isset($products[$id])||!is_int($n)||$n<1||$n>99)throw new InvalidArgumentException('Invalid cart.');$seen[$id]=true;$p=$products[$id];if(empty($p['eligible']))continue;$qty+=$n;$titles[strtolower(trim($p['title']))]=true;}if(((int)$r['distinctGames']?count($titles):$qty)<(int)$r['minQuantity'])throw new InvalidArgumentException('Requires at least '.$r['minQuantity'].((int)$r['distinctGames']?' different games.':' game items.'));return $r;}
function mcCreate(PDO $db,array $in): array {mcSchema($db);foreach(['percent'=>[1,100],'quantity'=>[1,100],'minQuantity'=>[1,9999],'useLimit'=>[0,1000000],'expires'=>[0,4102444800]] as $k=>$bounds){if(!isset($in[$k])||!is_int($in[$k])||$in[$k]<$bounds[0]||$in[$k]>$bounds[1])throw new InvalidArgumentException('Invalid '.$k);}if($in['expires']&&$in['expires']<=time())throw new InvalidArgumentException('Expiry must be in the future.');$name=strtoupper(trim((string)($in['name']??'')));if($name!==''&&!preg_match('/^[A-Z0-9][A-Z0-9-]{0,39}$/D',$name))throw new InvalidArgumentException('Use letters, numbers and hyphens for the name.');if(preg_match('/^OFA-(ADA|RWD|OPEN|SINGLE)/',$name))throw new InvalidArgumentException('Reserved coupon prefix.');$catalog=json_decode(file_get_contents(__DIR__.'/reward-catalog.json'),true);$out=[];$db->exec('BEGIN IMMEDIATE');try{for($i=1;$i<=$in['quantity'];$i++){$code=$name!==''?$name.($in['quantity']>1?'-'.str_pad((string)$i,3,'0',STR_PAD_LEFT):''):'OFA-CUSTOM-'.strtoupper(bin2hex(random_bytes(10)));if(isset($catalog['promos'][$code])||mcGet($db,$code))throw new InvalidArgumentException('Code already exists: '.$code);$db->prepare('INSERT INTO managed_coupons VALUES(?,?,?,?,?,?,?,?)')->execute([$code,$in['percent'],$in['minQuantity'],!empty($in['distinct'])?1:0,$in['expires'],$in['useLimit'],'active',time()]);$out[]=mcPublic($db,mcGet($db,$code));}$db->exec('COMMIT');return $out;}catch(Throwable $e){$db->exec('ROLLBACK');throw $e;}}
if(realpath($_SERVER['SCRIPT_FILENAME']??'')===__FILE__){http_response_code(404);exit;}
